    static final int TSIG_SIGNED = 3;
    static final int TSIG_FAILED = 4;
    public byte[] toWire() {
        DNSOutput out = new DNSOutput();
        toWire(out);
        size = out.current();
        return out.toByteArray();
    }
public void addRecord(Record r, int section);
